require_once __DIR__.'/../config/bootstrap.php';require_admin();$pid=(int)($_GET['product_id']??0);$p=db()->prepare('SELECT name FROM products WHERE id=?');$p->execute([$pid]);$product=$p->fetch();if(!$product){http_response_code(404);exit('Product not found');}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$label=trim((string)($_POST['variant_name']??''));$sku=trim((string)($_POST['sku']??''));$price=(float)($_POST['price']??0);$stock=max(0,(int)($_POST['stock_quantity']??0));$volume=(float)($_POST['volume_ml']??0);if($label&&$sku&&$price>0){$s=db()->prepare('INSERT INTO product_variants(product_id,variant_name,volume_ml,sku,price,stock_quantity) VALUES(?,?,?,?,?,?)');$s->execute([$pid,$label,$volume?:null,$sku,$price,$stock]);header('Location: /admin/variants.php?product_id='.$pid);exit;}$err='Enter a variant name, unique SKU and price greater than zero.';}$s=db()->prepare('SELECT * FROM product_variants WHERE product_id=? ORDER BY id DESC');$s->execute([$pid]);$rows=$s->fetchAll();$pageTitle='Product sizes — Ikki';require __DIR__.'/../includes/header.php';?>
<div class="admin-shell"><h1 class="page-title">Sizes · <?=e($product['name'])?></h1><nav class="admin-nav"><a href="/admin/">Dashboard</a><a href="/admin/products.php">Products</a></nav><?php if($err):?><p class="notice"><?=e($err)?></p><?php endif;?><form method="post" class="site-form"><?=csrf_field()?><div class="form-grid"><div><label class="field-label">Size label</label><input class="field" name="variant_name" placeholder="50ml" required></div><div><label class="field-label">Volume in ml</label><input class="field" name="volume_ml" type="number" step="0.01"></div><div><label class="field-label">Variant SKU</label><input class="field" name="sku" required></div><div><label class="field-label">Price (PKR)</label><input class="field" name="price" type="number" step="0.01" min="1" required></div><div><label class="field-label">Stock quantity</label><input class="field" name="stock_quantity" type="number" min="0" value="0"></div></div><p><button class="btn">Add size</button></p></form><table class="cart-table"><thead><tr><th>Variant</th><th>SKU</th><th>Price</th><th>Stock</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['variant_name'])?></td><td><?=e($r['sku'])?></td><td><?=money($r['price'])?></td><td><?=(int)$r['stock_quantity']?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';?>